SELECT name,value,changed,description FROM system.settings WHERE name IN ('max_threads','use_query_cache','enable_parallel_replicas','max_parallel_replicas','log_query_settings','log_queries','log_queries_probability','log_queries_min_query_duration_ms','use_query_condition_cache','use_uncompressed_cache','concurrency_control','max_memory_usage','allow_asynchronous_read_from_io_pool_for_merge_tree') ORDER BY name LIMIT 30 SETTINGS max_threads=2,max_execution_time=30,timeout_before_checking_execution_speed=0,max_rows_to_read=1000000000,max_bytes_to_read=100000000000,skip_unavailable_shards=0 FORMAT CSVWithNames